37	/**
38	 * Utility that can be used to invoke lambdas in a safe way. Primarily designed to help
39	 * support generically typed callbacks where {@link ClassCastException class cast
40	 * exceptions} need to be dealt with due to class erasure.
41	 *
42	 * @author Phillip Webb
43	 * @since 2.0.0
44	 */
45	public final class LambdaSafe {
46	
47		private static final @Nullable Method CLASS_GET_MODULE;
48	
49		private static final @Nullable Method MODULE_GET_NAME;
50	
51		static {
52			CLASS_GET_MODULE = ReflectionUtils.findMethod(Class.class, "getModule");
53			MODULE_GET_NAME = (CLASS_GET_MODULE != null)
54					? ReflectionUtils.findMethod(CLASS_GET_MODULE.getReturnType(), "getName") : null;
55		}
56	
57		private LambdaSafe() {
58		}
59	
60		/**
61		 * Start a call to a single callback instance, dealing with common generic type
62		 * concerns and exceptions.
63		 * @param callbackType the callback type (a {@link FunctionalInterface functional
64		 * interface})
65		 * @param callbackInstance the callback instance (may be a lambda)
66		 * @param argument the primary argument passed to the callback
67		 * @param additionalArguments any additional arguments passed to the callback
68		 * @param <C> the callback type
69		 * @param <A> the primary argument type
70		 * @return a {@link Callback} instance that can be invoked.
71		 */
72		public static <C, A> Callback<C, A> callback(Class<C> callbackType, C callbackInstance, A argument,
73				@Nullable Object @Nullable ... additionalArguments) {
74			Assert.notNull(callbackType, "'callbackType' must not be null");
75			Assert.notNull(callbackInstance, "'callbackInstance' must not be null");
76			return new Callback<>(callbackType, callbackInstance, argument, additionalArguments);
77		}
78	
79		/**
80		 * Start a call to callback instances, dealing with common generic type concerns and
81		 * exceptions.
82		 * @param callbackType the callback type (a {@link FunctionalInterface functional
83		 * interface})
84		 * @param callbackInstances the callback instances (elements may be lambdas)
85		 * @param argument the primary argument passed to the callbacks
86		 * @param additionalArguments any additional arguments passed to the callbacks
87		 * @param <C> the callback type
88		 * @param <A> the primary argument type
89		 * @return a {@link Callbacks} instance that can be invoked.
90		 */
91		public static <C, A> Callbacks<C, A> callbacks(Class<C> callbackType, Collection<? extends C> callbackInstances,
92				A argument, Object... additionalArguments) {
93			Assert.notNull(callbackType, "'callbackType' must not be null");
94			Assert.notNull(callbackInstances, "'callbackInstances' must not be null");
95			return new Callbacks<>(callbackType, callbackInstances, argument, additionalArguments);
96		}
97	
98		/**
99		 * Abstract base class for lambda safe callbacks.
100		 *
101		 * @param <C> the callback type
102		 * @param <A> the primary argument type
103		 * @param <SELF> the self class reference
104		 */
105		protected abstract static class LambdaSafeCallback<C, A, SELF extends LambdaSafeCallback<C, A, SELF>> {
106	
107			private final Class<C> callbackType;
108	
109			private final A argument;
110	
111			private final @Nullable Object @Nullable [] additionalArguments;
112	
113			private Log logger;
114	
115			private Filter<C, A> filter = new GenericTypeFilter<>();
116	
117			LambdaSafeCallback(Class<C> callbackType, A argument, @Nullable Object @Nullable [] additionalArguments) {
118				this.callbackType = callbackType;
119				this.argument = argument;
120				this.additionalArguments = additionalArguments;
121				this.logger = LogFactory.getLog(callbackType);
122			}
123	
124			/**
125			 * Use the specified logger source to report any lambda failures.
126			 * @param loggerSource the logger source to use
127			 * @return this instance
128			 */
129			public SELF withLogger(Class<?> loggerSource) {
130				return withLogger(LogFactory.getLog(loggerSource));
131			}
132	
133			/**
134			 * Use the specified logger to report any lambda failures.
135			 * @param logger the logger to use
136			 * @return this instance
137			 */
138			public SELF withLogger(Log logger) {
139				Assert.notNull(logger, "'logger' must not be null");
140				this.logger = logger;
141				return self();
142			}
143	
144			/**
145			 * Use a specific filter to determine when a callback should apply. If no explicit
146			 * filter is set filter will be attempted using the generic type on the callback
147			 * type.
148			 * @param filter the filter to use
149			 * @return this instance
150			 * @since 3.4.8

